	/**
	 * Default Constructor
	 */
    public TaxWithholdingService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new TaxWithholdingEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(TaxWithholdingRepository.class) );
		this.validator		= applicationContext.getBean(TaxWithholdingValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		TaxWithholding
	 */
		public TaxWithholding createTaxWithholding( CreateTaxWithholdingCommand command ) {

		TaxWithholding entity = new TaxWithholding();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setTaxWithholdingId( command.getTaxWithholdingId() );
            entity.setTaxId( command.getTaxId() );
            entity.setAllowances( command.getAllowances() );
            entity.setAdditionalAmount( command.getAdditionalAmount() );
            entity.setFilingStatus( command.getFilingStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of TaxWithholding {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateTaxWithholdingCommand
	 * @return		TaxWithholding
	 */
	public TaxWithholding updateTaxWithholding( UpdateTaxWithholdingCommand command ) {

		TaxWithholding entity = new TaxWithholding();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setTaxWithholdingId( command.getTaxWithholdingId() );
            entity.setTaxId( command.getTaxId() );
            entity.setAllowances( command.getAllowances() );
            entity.setAdditionalAmount( command.getAdditionalAmount() );
            entity.setEmployee( command.getEmployee() );
            entity.setFilingStatus( command.getFilingStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of TaxWithholding {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteTaxWithholdingCommand
	 */
	public void delete( DeleteTaxWithholdingCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getTaxWithholdingId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of TaxWithholding {0} ", id );

	}

	/**
	 * Method to retrieve the TaxWithholding via TaxWithholdingFetchOneSummary
	 * @param 	summary TaxWithholdingFetchOneSummary
	 * @return 	TaxWithholdingFetchOneResponse
	 */
	public TaxWithholding getTaxWithholding( TaxWithholdingFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "TaxWithholdingFetchOneSummary arg cannot be null" );

		TaxWithholding entity = null;
		UUID id = summary.getTaxWithholdingId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a TaxWithholding using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all TaxWithholdings
	 *
	 * @return 	List<TaxWithholding>
	 */
    public List<TaxWithholding> getAllTaxWithholding() {
		List<TaxWithholding> list = projector.findAll( new FindAllTaxWithholdingQuery() );
		return list;
	}

	/**
	 * assign Employee on TaxWithholding
	 * @param		command AssignEmployeeToTaxWithholdingCommand
	 */
	public void assignEmployee( AssignEmployeeToTaxWithholdingCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignEmployee(command.getTaxWithholdingId(), command.getAssignment());

	}

	/**
	 * unAssign Employee on TaxWithholding
	 * @param		command UnAssignEmployeeFromTaxWithholdingCommand
	 */
	public void unAssignEmployee( UnAssignEmployeeFromTaxWithholdingCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignEmployee(command.getTaxWithholdingId());
	}
	




